<?php use VazinCMS\Security; ?><section class="title"><div><h1>کدهای تخفیف</h1><p>ساخت، زمان‌بندی و کنترل مصرف تخفیف‌ها</p></div></section>
<?php if($error):?><div class="alert error"><?=Security::e($error)?></div><?php endif;?><section class="split"><div class="panel"><h2>کد جدید</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>کد<input name="code" minlength="3" maxlength="40" placeholder="WELCOME20" required></label><label>نوع<select name="type"><option value="percent">درصدی</option><option value="fixed">مبلغ ثابت</option></select></label><label>مقدار<input type="number" name="value" min="0.01" step="0.01" required></label><label>حداقل سفارش<input type="number" name="minimum_amount" min="0" step="0.01" value="0"></label><label>ارز (برای همه خالی بگذارید)<input name="currency" maxlength="8" placeholder="RUB"></label><label>حداکثر مصرف<input type="number" name="max_uses" min="1"></label><label>شروع<input type="datetime-local" name="starts_at"></label><label>پایان<input type="datetime-local" name="expires_at"></label><button>ساخت کد تخفیف</button></form></div><div class="panel"><h2>کدهای ثبت‌شده</h2><div class="table-wrap"><table><thead><tr><th>کد</th><th>تخفیف</th><th>مصرف</th><th>اعتبار</th><th>وضعیت</th></tr></thead><tbody><?php foreach($discounts as $d):?><tr><td><b><?=Security::e($d['code'])?></b></td><td><?=Security::e($d['type']==='percent'?$d['value'].'٪':$d['value'].' '.($d['currency']?:''))?></td><td><?=Security::e($d['used_count'].' / '.($d['max_uses']??'∞'))?></td><td><?=Security::e((string)($d['expires_at']??'بدون انقضا'))?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$d['id']?>"><button class="secondary"><?=$d['is_active']?'فعال':'غیرفعال'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div></section>
